create table if not exists qa472.cases(label text primary key,x jsonb not null);create or replace function qa472.make_case(label text,quantity numeric default 100)returns jsonb language plpgsql as $$declare ctx jsonb;f uuid;a uuid;l uuid;m uuid;c uuid;s uuid;i uuid;result jsonb;begin select x into ctx from qa472.context;f:=(ctx->>'factory')::uuid;a:=(ctx->>'owner')::uuid;perform set_config('request.jwt.claim.sub',a::text,true);select x into result from qa472.cases where cases.label=make_case.label;if found then return result;end if;insert into public.production_lines(factory_id,name,code)values(f,'QA '||label,'QA-L-'||label)returning id into l;select category_id into c from public.work_centers where id=(ctx->>'machine')::uuid;insert into public.work_centers(factory_id,line_id,category_id,name,code,status,dependency_mode,impact_scope)values(f,l,c,'QA processor '||label,'QA-M-'||label,'running','blocking','whole_line')returning id into m;perform public.configure_center_capabilities(f,m,jsonb_build_array(jsonb_build_object('product_id',ctx->'products'->>1,'rate',90,'rate_unit','meter','setup_minutes',0)));s:=public.create_sales_order(f,jsonb_build_object('customer_reference','Group471 '||label,'lines',jsonb_build_array(jsonb_build_object('product_id',ctx->'products'->>1,'quantity',quantity,'unit','meter'))),gen_random_uuid());perform public.approve_sales_order(f,s,gen_random_uuid());select po.id into i from public.production_orders po join public.production_requests pr on pr.id=po.request_id join public.sales_order_lines sl on sl.id=pr.sales_order_line_id where sl.order_id=s;perform public.plan_product_item(f,i,l,clock_timestamp()+interval '1 minute');result:=jsonb_build_object('factory',f,'owner',a,'line',l,'machine',m,'item',i,'sales',s,'quantity',quantity,'raw',(ctx->'materials'->>0),'masterbatch',(ctx->'materials'->>1),'additive',(ctx->'materials'->>2));insert into qa472.cases values(label,result);return result;end$$;